# 基差正負對應「正價差／逆價差」，避免硬編碼在基差轉負時標錯
def _basis_label():
    v = float(str(DERIVATIVES["futures_basis"]).replace(",", "").replace("+", ""))
    if v > 0: return "正價差"
    if v < 0: return "逆價差"
    return "平價"
# 量能標籤：依當日成交量與 5 日均量的實際關係計算，避免硬編「量縮整理」在放量日標錯
def _vol_label():
    v  = float(str(STOCK["tw_volume"]).replace(",", ""))
    ma = float(str(TECHNICAL["vol_ma5"]).replace(",", ""))
    if ma <= 0:
        return "量能待確認", "#607D8B"
    d = (v / ma - 1) * 100
    if d >= 20:  return f"明顯放量 (+{d:.0f}% vs 均量)", "#F44336"
    if d >= 3:   return f"量增 (+{d:.0f}% vs 均量)",     "#4CAF50"
    if d > -3:   return "量能持平 (約當均量)",            "#607D8B"
    if d > -20:  return f"量縮 ({d:.0f}% vs 均量)",       "#607D8B"
    return f"明顯量縮 ({d:.0f}% vs 均量)", "#FF9800"
VOL_LABEL, VOL_LABEL_COLOR = _vol_label()

# 布林位置標籤：依現價與上／中／下軌的實際關係計算，避免硬編方向性描述
def _bb_label():
    px = float(str(STOCK["tw_price"]).replace(",", ""))
    up = float(str(TECHNICAL["bb_upper"]).replace(",", ""))
    md = float(str(TECHNICAL["bb_mid"]).replace(",", ""))
    lo = float(str(TECHNICAL["bb_lower"]).replace(",", ""))
    if px > up: return "突破上軌", "#F44336"
    if px >= up: return "觸及上軌", "#F44336"
    if px < lo: return "跌破下軌", "#2196F3"
    if px <= lo: return "觸及下軌", "#2196F3"
    if px >= md: return "中軌之上", "#4CAF50"
    return "中軌之下", "#FF9800"
BB_LABEL, BB_LABEL_COLOR = _bb_label()

BASIS_LABEL = _basis_label()

# P/C 未平倉比標籤：依實際比值分段計算，避免硬編「偏空」在比值接近 1 或小於 1 時標錯
def _pcr_label():
    r = float(DERIVATIVES["pcr"])
    if r >= 1.20: return "偏空（賣權未平倉明顯偏多）", "#F44336"
    if r >= 1.05: return "中性偏空（賣權略多）", "#FF9800"
    if r >= 0.95: return "中性（多空未平倉均衡）", "#607D8B"
    if r >= 0.80: return "中性偏多（買權略多）", "#8BC34A"
    return "偏多（買權未平倉明顯偏多）", "#4CAF50"
