IR_RECENT_N = 20       # 日報 IR 行事曆顯示條數（取 IR_ALL 最後 N 條）
TRIGGERS_RECENT_N = 10  # 日報 EPS 催化因子顯示條數（取 TRIGGERS_ALL 前 N 條）

def _load_archive(name):
    """讀 history/<name>.json；不存在回 []。tuple 以 list 存檔，載入時轉回 tuple。"""
    fp = os.path.join(HISTORY_DIR, name + ".json")
    if not os.path.exists(fp):
        return []
    with open(fp, "r", encoding="utf-8") as f:
        return [tuple(x) for x in json.load(f)]

IR_ARCHIVE = _load_archive("ir_calendar_archive")                 # 升冪、較舊
EPS_TRIGGER_ARCHIVE = _load_archive("eps_triggers_archive")       # 降冪、較舊
# 工作集與 archive 重疊時以工作集為準（IR 以 (date,title) 為 key；triggers 以整條為 key）
_ir_keys = {(r[0], r[1]) for r in IR_CALENDAR}
